// Calcula huecos disponibles L-V de 10:00 a 13:00 respetando duracion_minutos
const query = $('Webhook GET Disponibilidad').first().json.query || {};
const fecha = query.fecha;
const modalidad = query.modalidad || 'in_situ';
const numCuchillos = Math.max(1, parseInt(query.num_cuchillos || '1', 10));
const duracionMinutos = modalidad === 'recogida' ? 25 : Math.max(15, numCuchillos * 5) + 20;

const events = $input.all().map(i => i.json).filter(e => e.start && e.end);

function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const busyBlocks = events.map(ev => {
  const startDt = new Date(ev.start.dateTime || ev.start.date);
  const endDt = new Date(ev.end.dateTime || ev.end.date);
  const sMin = startDt.getHours() * 60 + startDt.getMinutes();
  const eMin = endDt.getHours() * 60 + endDt.getMinutes();
  return { startMin: sMin, endMin: eMin };
});

const candidates = ['10:00', '10:30', '11:00', '11:30', '12:00', '12:30'];
const maxCloseMin = 13 * 60 + 25; // 13:25 margen máximo

const availableSlots = candidates
  .filter(slot => {
    const sMin = toMinutes(slot);
    const eMin = sMin + duracionMinutos;
    if (eMin > maxCloseMin) return false;
    const overlaps = busyBlocks.some(b => sMin < b.endMin && eMin > b.startMin);
    return !overlaps;
  })
  .map(slot => ({
    time: slot,
    endTime: toHHMM(toMinutes(slot) + duracionMinutos)
  }));

return [{
  json: {
    ok: true,
    fecha,
    modalidad,
    num_cuchillos: numCuchillos,
    duracion_minutos: duracionMinutos,
    slots: availableSlots
  }
}];

// Valida reglas de negocio (CP 28224, L-V 10:00-13:00, duración y genera archivo .ics)
const body = $input.first().json.body || $input.first().json;

if (String(body.codigo_postal).trim() !== '28224') {
  throw new Error('Código postal fuera de zona: solo activo en CP 28224.');
}

const modalidad = body.modalidad === 'recogida' ? 'recogida' : 'in_situ';
const numCuchillos = Math.max(1, parseInt(body.num_cuchillos || 1, 10));
const duracionMinutos = modalidad === 'recogida' ? 25 : Math.max(15, numCuchillos * 5) + 20;

const [h, m] = String(body.hora_inicio || '10:00').split(':').map(Number);
const startMin = h * 60 + m;
const endMin = startMin + duracionMinutos;
const horaFin = `${String(Math.floor(endMin / 60)).padStart(2, '0')}:${String(endMin % 60).padStart(2, '0')}`;

const dateClean = String(body.fecha).replace(/-/g, '');
const dtStart = `${dateClean}T${String(h).padStart(2, '0')}${String(m).padStart(2, '0')}00`;
const dtEnd = `${dateClean}T${horaFin.replace(':', '')}00`;

const summary = `Kusin Afilado (${modalidad === 'in_situ' ? 'In Situ' : 'Recogida 24/48h'}) - ${body.nombre}`;
const description = `Servicio vecinal CP 28224. Modalidad: ${modalidad}. Cuchillos filo liso: ${numCuchillos} (el peor gratis). Dirección: ${body.direccion}. Notas: ${body.notas || 'Sin notas'}`;

const icsContent = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Madkusin Vecindario 28224//ES',
  'BEGIN:VEVENT',
  `SUMMARY:${summary}`,
  `DTSTART;TZID=Europe/Madrid:${dtStart}`,
  `DTEND;TZID=Europe/Madrid:${dtEnd}`,
  `LOCATION:${body.direccion}, 28224 Pozuelo de Alarcón`,
  `DESCRIPTION:${description}`,
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');

return [{
  json: {
    ...body,
    modalidad,
    num_cuchillos: numCuchillos,
    duracion_minutos: duracionMinutos,
    hora_fin: horaFin,
    start_iso: `${body.fecha}T${body.hora_inicio}:00`,
    end_iso: `${body.fecha}T${horaFin}:00`,
    ics_base64: Buffer.from(icsContent, 'utf-8').toString('base64')
  }
}];

